            "**冲量**：$\\vec I=\\int\\vec F\\,dt$，是力对时间的累积，是过程量、矢量。恒力的冲量 $\\vec I=\\vec F\\Delta t$；变力必须积分。冲量的方向一般不等于力的方向，而等于动量增量的方向。",
            "**动量定理**：合外力的冲量等于动量的增量。直角坐标下可分方向使用：$I_x=\\Delta p_x$、$I_y=\\Delta p_y$。某一方向不受力或冲量为零时，该方向动量守恒。",
            "**平均冲力**：$\\bar F=\\Delta p/\\Delta t$。碰撞、打击过程中作用时间极短，即使平均冲力很大，冲量仍有限；缓冲（延长作用时间）可以减小冲力。",
