            "**角量**：角位移 $\\Delta\\theta$、角速度 $\\omega$、角加速度 $\\alpha$。角速度方向沿转轴，由右手螺旋定则确定；定轴转动中可用正负号表示方向。",
            "**线量与角量**：$v=r\\omega$，$a_t=r\\alpha$，$a_n=r\\omega^2$。同一刚体上不同点到轴的距离 $r$ 不同，线速度、线加速度不同，但角量相同。",
            "**匀角加速转动**：$\\alpha$ 为常量时，三个角量公式与匀变速直线运动公式对应；解题时先规定转动正方向，再统一符号。",
            "**传动关系**：皮带传动、齿轮传动中，轮缘线速度大小相等（无滑动），$\\omega_1r_1=\\omega_2r_2$；同轴转动各轮角速度相同。"
