            "**速度与加速度**：速度最大值 $v_m=\\omega A$，加速度最大值 $a_m=\\omega^2A$。在平衡位置 $x=0$ 时速度最大、加速度为零；在最大位移处速度为零、加速度最大且指向平衡位置。"
