              "solution": "$L=nr=1.5\\times0.20=0.30\\,\\text{m}$；$\\Delta\\varphi=2\\pi L/\\lambda=2\\pi\\times0.30/(600\\times10^{-9})=1.0\\times10^6\\pi$。"
