        {
          "id": "k14-6",
          "title": "光的偏振",
          "summary": "光是横波，光矢量振动方向垂直于传播方向。自然光中各方向振动均匀分布；线偏振光只在一个方向振动。偏振片、反射和折射、双折射都可产生或检验偏振光。",
          "formulas": [
            {
              "tex": "I=I_0\\cos^2\\theta",
              "note": "马吕斯定律：线偏振光通过检偏器后的光强"
            },
            {
              "tex": "\\tan i_B=\\frac{n_2}{n_1}",
              "note": "布儒斯特定律：反射光为完全线偏振光"
            },
            {
              "tex": "i_B+r=90^\\circ",
              "note": "布儒斯特角入射时，反射光与折射光垂直"
            }
          ],
          "points": [
            "**自然光与偏振光**：自然光中光矢量在各方向均匀分布，强度相等；线偏振光光矢量只沿一个固定方向振动；部分偏振光介于二者之间。",
            "**偏振片**：只允许某一方向光振动通过，该方向为偏振化方向（透振方向）。自然光通过偏振片后变为线偏振光，光强减半。",
            "**马吕斯定律**：线偏振光通过检偏器，$I=I_0\\cos^2\\theta$，$\\theta$ 为入射光振动方向与检偏器透振方向的夹角。$\\theta=0$ 最强，$\\theta=90^\\circ$ 消光。",
            "**布儒斯特定律**：自然光从折射率 $n_1$ 介质射向 $n_2$ 介质，入射角满足 $\\tan i_B=n_2/n_1$ 时，反射光为完全线偏振光，振动方向垂直于入射面；折射光为部分偏振光。",
            "**双折射**：某些晶体（如方解石）对寻常光和非常光折射率不同，一束光分为两束；二者都是线偏振光，振动方向相互垂直。"
          ],
          "pitfalls": [
            "认为自然光通过偏振片后光强不变；理想偏振片下光强减半。",
            "马吕斯定律中角度用错；$\\theta$ 是入射偏振方向与检偏器透振方向的夹角。",
            "认为反射光一定是完全偏振光；只有以布儒斯特角入射时反射光才完全偏振。",
            "把布儒斯特角公式中的 $n_1,n_2$ 写反；$\\tan i_B=n_2/n_1$（从 $n_1$ 射向 $n_2$）。"
          ],
          "examples": [
            {
              "question": "自然光通过两个偏振化方向成 $60^\\circ$ 的偏振片。求透射光强与入射自然光强之比。",
              "solution": "通过第一片后光强 $I_1=I_0/2$，且为线偏振光；通过第二片后 $I_2=I_1\\cos^2 60^\\circ=\\frac{I_0}{2}\\times\\frac14=\\frac{I_0}{8}$。"
            }
          ]
        }
